package ociresources

import (
	"log"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/cache"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/registrymgr"
	"github.com/anthnel/devdesk/internal/trust"
)

// openMultiRegistryBrowser opens the multi-registry browser (triggered by 'b' on Images tab).
func (m Model) openMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if len(m.registries) == 0 {
		return m, m.footer.Warn("No registries configured — add one in the Registries tab")
	}
	// Config plus cache, read here and now: no network, no waiting, no state
	// that ignores esc (D13).
	// Reopening replaces a browser that may still have a lot in flight.
	m.registryBrowser.cancelInFlight()
	m.registryBrowser = newRegistryBrowser(m.registries, m.groupCache, m.browserDeselected, m.width-2, m.height)
	m.registryBrowser.SetScanCache(m.scanCache)
	m.registryBrowser.SetJobs(m.jobs, m.failures, m.contextName)
	return m, nil
}

// closeMultiRegistryBrowser drops the browser, remembering what the user
// unchecked so the next visit opens on the same selection.
func (m Model) closeMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil {
		return m, nil
	}
	m.registryBrowser.cancelInFlight()
	deselected := m.registryBrowser.Deselected()
	m.registryBrowser = nil

	m.browserDeselected = make(map[string]bool, len(deselected))
	for _, key := range deselected {
		m.browserDeselected[key] = true
	}
	return m, saveBrowserSelectionCmd(deselected)
}

// handleMultiRegistryTagsLoaded incorporates tag results from one registry into the browser.
func (m Model) handleMultiRegistryTagsLoaded(msg MultiRegistryTagsLoadedMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || msg.Gen != m.registryBrowser.gen {
		return m, nil
	}
	if msg.Err != nil {
		m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, nil)
		if m.registryBrowser.tagsFromSearch {
			log.Printf("ERROR [oci_resources] registry tags on %s: %s", msg.Alias, searchErrorCause(msg.Err))
			return m, m.footer.Error(tagsLoadFailedText)
		}
		log.Printf("ERROR [oci_resources] registry tags %s from %s: %v", msg.Repo, msg.RegistryURL, msg.Err)
		return m, nil
	}
	m.registryBrowser.SetScanCache(m.scanCache)
	m.registryBrowser.AddRegistryTags(msg.EntryKey, msg.RegistryURL, msg.Alias, msg.Repo, msg.Tags)
	return m, loadMultiRegistryTagsMetaCmd(msg.Gen, msg.EntryKey, msg.RegistryURL, msg.Repo)
}

// handleMultiRegistryTagsMeta stores tag metadata for one registry in the browser.
func (m Model) handleMultiRegistryTagsMeta(msg MultiRegistryTagsMetaMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || msg.Gen != m.registryBrowser.gen {
		return m, nil
	}
	if msg.Err != nil {
		log.Printf("INFO [oci_resources] tag meta unavailable for %s at %s: %v", msg.Repo, msg.RegistryURL, msg.Err)
		return m, nil
	}
	if msg.Meta != nil {
		m.registryBrowser.SetMultiTagsMeta(msg.EntryKey, msg.Meta)
	}
	return m, nil
}

// handleRegistryPullRequested admits a browser pull as a job and puts the user
// where they can watch it: the Images tab, browser closed (§3.60).
//
// A pull is asked for from the browser and answered in the Images list, and
// leaving the user on the browser's own spinner meant the one screen that could
// not show either the progress or the result. The switch happens here, once, on
// the keypress that asked for it — it is not a work message dragging the screen
// around behind the user's back, which is what D67 forbids.
func (m Model) handleRegistryPullRequested(msg RegistryPullRequestedMsg) (tea.Model, tea.Cmd) {
	if m.pullingImage(msg.ImageName) {
		return m, m.footer.Warn("Pull already in progress")
	}
	start := jobs.Start(m.pullRun(msg.ImageName), pullOneImageCmd(msg.ImageName, m.pullDeps()))

	// closeMultiRegistryBrowser carries the deselection the next visit reopens
	// on, so the browser is closed through it rather than by hand.
	closed, closeCmd := m.closeMultiRegistryBrowser()
	next, ok := closed.(Model)
	if !ok {
		return closed, tea.Batch(closeCmd, start)
	}
	next.activeTab = tabImages
	next.updateImageTable()
	return next, tea.Batch(closeCmd, start)
}

// handleRegistryPullComplete processes the result of a pull.
//
// It does not depend on the browser any more: the pull outlives it now that
// asking for one closes it, and a completion that returned early on a nil

