// swap it.
var listRegistryTags = oci.ListRegistryTagsContext

// nextBrowserGen returns a fresh generation. Called from Update only (Rule 110).
func nextBrowserGen() uint64 { return browserGen.Add(1) }

// beginRequests cancels the lot in flight and opens a new one: a new
// generation, a fresh context, no pending search. Call it only once a request
// is certain to start, so a refused validation leaves the running lot alone.
func (b *RegistryBrowser) beginRequests() context.Context {
	b.cancelInFlight()
	ctx, cancel := context.WithCancel(context.Background())
	b.cancel = cancel
	b.gen = nextBrowserGen()
	b.pendingSearches = 0
	return ctx
}

// cancelInFlight cancels the lot's context, if any. Nil-safe.
func (b *RegistryBrowser) cancelInFlight() {
	if b == nil || b.cancel == nil {
		return
	}
	b.cancel()
	b.cancel = nil
}

// RegistryBrowserGen returns the generation the open browser accepts, 0 when it
// is closed. For tests, like ActivityTables.
func (m Model) RegistryBrowserGen() uint64 {
	if m.registryBrowser == nil {
		return 0
	}
	return m.registryBrowser.gen
}

// defaultImageSearcher is what a browser opens with: Docker Hub anonymously,
// any other registry answers imagesearch.ErrUnsupported without a request
// (IS-03 adds the others). Tests replace it before opening the browser.
var defaultImageSearcher imagesearch.Searcher = imagesearch.ByRegistry(imagesearch.HubSearcher{}, nil)

// imageSearchDeadline bounds one registry's whole search.
var imageSearchDeadline = 15 * time.Second

// targetFor describes entry for the Searcher, with the same alias, address and
// credentials (D12) the tag flow uses.
func (b *RegistryBrowser) targetFor(entry browserRegistryEntry) imagesearch.Target {
	user, pass := b.credsFor(entry)
	return imagesearch.Target{
		EntryKey: entry.key, Alias: entryAlias(entry), RegistryURL: entry.URL,
		APIURL: registryAPIURL(entry.URL), RepoPrefix: entry.repoPrefix,
	}

	b.state = browserStateTags
	b.searchTable.Blur()
	b.tagTable.Focus()
	b.rebuildTagTable()
	return b, tea.Batch(cmds...)
}

func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.filterActive {
		switch msg.String() {
		case "esc", "enter":
			b.filterActive = false
			b.filterInput.Blur()
			b.rebuildTagTable()
			b.resizeTables()
			return b, nil
		}
		return b.delegateUpdate(msg)
	}

	switch msg.String() {
	case "esc":
		b.state = browserStateInput
		b.tagTable.Blur()
		b.updateFocus()
		return b, nil
	case "/":
		b.filterActive = true
		b.filterInput.Focus()
		b.resizeTables()
		return b, nil
	case "r":
		b.cycleRegistryFilter()
		return b, nil
	case "enter":
		return b.openTagScanDetails()
	case keymap.Get:
		return b.pullSelectedTag()
	case keymap.Scan:
		return b.requestDirectScan()
	}
	// Navigation and `.` are the table's. `/` never reaches it: the browser's
	// own filter took the key two cases above, and the table declares no
	// searchable column, so it would decline it anyway.
	return b, b.tagTable.Update(msg)
}
	b.rebuildTagTable()
}

// entryFor returns the browser entry a result came from, or nil.
//
// It resolves by entry key, not by URL: every member of a path-routed group
// answers to the same host, so a URL identifies a whole instance and a result
// would be unattributable (§3.18, and D40 one screen along).
func (b *RegistryBrowser) entryFor(key string) *browserRegistryEntry {
	for i := range b.entries {
		if b.entries[i].key == key {
			return &b.entries[i]
		}
	}
	return nil
}

// registryFilterLabel returns a short display label for the active filter.
//
// D14: it used to search only the configured top-level entries, so filtering to
// a discovered member fell through to the synthesised URL — the one row in the
// view showing a URL where every other showed an alias. Members are entries now,
// so they resolve like anything else.
func (b *RegistryBrowser) registryFilterLabel() string {
	if b.registryFilter.groupSlug != "" {
		for _, reg := range b.registries {
